  "fig.rat.hint": "Click the rat for another one",
  "fig.rat.caption": "One of the {n} random rats there will ever be, drawn in your browser from a random seed. Click it and another one lands.",
  "fig.vs.box": "A box",
  "fig.vs.rat": "A rat",
  "fig.vs.what": "What it is",
